	}
	decoder := json.NewDecoder(bytes.NewReader(raw))
	decoder.DisallowUnknownFields()
	return decoder.Decode(&f.Value)
}

func (f Field[T]) MarshalJSON() ([]byte, error) {
	if err := f.validateField(); err != nil {
		return nil, err
	}
	if !f.Set || f.Null {
		return []byte("null"), nil
	}

	if v, ok := any(f.Value).(int64); ok {
		return json.Marshal(strconv.FormatInt(v, 10))
	}
	return json.Marshal(f.Value)
}

func (p *ApplyPrice) UnmarshalJSON(raw []byte) error {
	type price ApplyPrice
	var decoded struct {
		price
		Amount          Field[string] `json:"amount,omitzero"`
		AccessDuration  Field[string] `json:"access_duration,omitzero"`
		BillingInterval Field[string] `json:"billing_interval,omitzero"`
		TrialDuration   Field[string] `json:"trial_duration,omitzero"`
	}
	decoder := json.NewDecoder(bytes.NewReader(raw))
	decoder.DisallowUnknownFields()
	if err := decoder.Decode(&decoded); err != nil {
		return err
	}
	if decoded.Amount.Set {
		if decoded.Amount.Null {
			return fmt.Errorf("amount cannot be null")
		}
		if decoded.UnitAmount.Set || decoded.Currency.Set {
			return fmt.Errorf("amount cannot be combined with unit_amount or currency")
		}
		amount, currency, err := parseAmount(decoded.Amount.Value)
		if err != nil {
			return fmt.Errorf("amount: %w", err)
		}
		decoded.UnitAmount = Value(amount)
		decoded.Currency = Value(currency)
	}
	if decoded.BillingInterval.Set {
		if decoded.BillingIntervalHours.Set || decoded.BillingIntervalMonths.Set {
			return fmt.Errorf("billing_interval cannot be combined with billing_interval_hours or billing_interval_months")
		}
		decoded.BillingIntervalHours = Null[int]()
		if !decoded.BillingInterval.Null {
			hours, months, err := syntax.ParseBillingInterval(decoded.BillingInterval.Value)
			if err != nil {
				return err
			}
			if months > 0 {
				decoded.BillingIntervalMonths = Value(months)
			} else {
				decoded.BillingIntervalHours = Value(hours)
			}
		}
	}
	for _, field := range []struct {
		name  string
		text  Field[string]
		hours *Field[int]
	}{
		{"trial_duration", decoded.TrialDuration, &decoded.TrialDurationHours},
	} {
		if !field.text.Set {
			continue
		}
		if field.hours.Set {
			return fmt.Errorf("%s and %s_hours cannot both be set", field.name, field.name)
		}
		if field.text.Null {
			*field.hours = Null[int]()
			continue
		}
		hours, err := syntax.ParseDurationHours(field.text.Value)
		if err != nil {
			return fmt.Errorf("%s: %w", field.name, err)
		}
		*field.hours = Value(hours)
	}
	if decoded.AccessDuration.Set {
		if decoded.AccessDurationHours.Set {
			return fmt.Errorf("access_duration and access_duration_hours cannot both be set")
		}
		hours, err := parseAccessDuration(decoded.AccessDuration)
		if err != nil {
			return err
		}
		decoded.AccessDurationHours = hours
		if decoded.BillingIntervalMonths.Set && !decoded.BillingIntervalMonths.Null && hours.Null {
			return fmt.Errorf("a calendar price cannot grant access forever; omit access_duration to follow its billing period")
		}
	}
	*p = ApplyPrice(decoded.price)
	return nil
}

func (p *ApplyProviderPrice) UnmarshalJSON(raw []byte) error {
	type provider ApplyProviderPrice
	var decoded struct {
		provider
		UnitAmount      Field[int64]  `json:"unit_amount,omitzero"`
		TrialUnitAmount Field[int64]  `json:"trial_unit_amount,omitzero"`
		Amount          *string       `json:"amount,omitempty"`
		AccessDuration  Field[string] `json:"access_duration,omitempty"`
		BillingInterval *string       `json:"billing_interval,omitempty"`
		TrialDuration   *string       `json:"trial_duration,omitempty"`
	}
	decoder := json.NewDecoder(bytes.NewReader(raw))
	decoder.DisallowUnknownFields()
	if err := decoder.Decode(&decoded); err != nil {
		return err
	}

	for _, money := range []struct {
		field Field[int64]
		into  **int64
	}{{decoded.UnitAmount, &decoded.provider.UnitAmount}, {decoded.TrialUnitAmount, &decoded.provider.TrialUnitAmount}} {
		if money.field.Null {
			return fmt.Errorf("money cannot be null")
		}
		if money.field.Set {
			value := money.field.Value
			*money.into = &value
		}
	}
	if decoded.Amount != nil {
		if decoded.provider.UnitAmount != nil || decoded.Currency != "" {
			return fmt.Errorf("amount cannot be combined with unit_amount or currency")
		}
		amount, code, err := parseAmount(*decoded.Amount)
		if err != nil {
			return fmt.Errorf("amount: %w", err)
		}
		decoded.provider.UnitAmount, decoded.Currency = &amount, code
	}
	for _, field := range []struct {
		name  string
		text  *string
		hours **int
	}{
		{"billing_interval", decoded.BillingInterval, &decoded.BillingIntervalHours},
		{"trial_duration", decoded.TrialDuration, &decoded.TrialDurationHours},
	} {
		if field.text == nil {
			continue
		}
		if *field.hours != nil {
			return fmt.Errorf("%s and %s_hours cannot both be set", field.name, field.name)
		}
		hours, err := syntax.ParseDurationHours(*field.text)
		if err != nil {
			return fmt.Errorf("%s: %w", field.name, err)
		}
		*field.hours = &hours
	}
	if decoded.AccessDuration.Set {
		if decoded.AccessDurationHours.Set {
			return fmt.Errorf("access_duration and access_duration_hours cannot both be set")
		}
		hours, err := parseAccessDuration(decoded.AccessDuration)
		if err != nil {
			return err
		}
		decoded.AccessDurationHours = hours
	}
	*p = ApplyProviderPrice(decoded.provider)
	return nil
}

